args.sql:
SELECT ROUND(CAST(
  (SELECT COUNT(*) FROM traders t LEFT JOIN trade_records tr ON tr.tr_anchor = t."TR_KEY" 
   WHERE ((AVG((tr.trade_perf->>'lev_ratio')::numeric)) > 5.0 AND t.trader_fin_data->>'risk_lvl' = 'Aggressive') 
      OR (COALESCE(SUM(tr.vol_day), 0) / NULLIF(REGEXP_REPLACE(t.trader_fin_data->>'usd_bal', '[\$, ]', '', 'g')::numeric, 0) > 0.5)
  ) * 100.0 / (SELECT COUNT(*) FROM traders) AS numeric), 2);

